#include <bits/stdc++.h>
using namespace std;
int main() {
  int k, n;
  scanf("%d%d", &n, &k);
  vector<int> a(n), b(n), distributed(n), p(n);
  vector<vector<int> > cart(k);
  for (int i = 0; i < n; ++i) {
    scanf("%d%d", &a[i], &b[i]);
    distributed[i] = 0;
    p[i] = i;
  }
  for (int i = 0; i < n; ++i) {
    for (int j = i + 1; j < n; ++j) {
      if (a[p[i]] < a[p[j]]) {
        swap(p[i], p[j]);
      }
    }
  }
  int cart_ptr = 0;
  for (int i = 0; i < n && cart_ptr < k; ++i) {
    if (b[p[i]] == 1) {
      distributed[p[i]] = 1;
      cart[cart_ptr].push_back(p[i]);
      ++cart_ptr;
    }
  }
  deque<int> available;
  for (int i = 0; i < n; ++i) {
    if (!distributed[p[i]]) {
      available.push_back(p[i]);
    }
  }
  while (cart_ptr < k) {
    cart[cart_ptr].push_back(available.front());
    available.pop_front();
    ++cart_ptr;
  }
  while (!available.empty()) {
    cart[k - 1].push_back(available.front());
    available.pop_front();
  }
  long long ans = 0;
  for (int i = 0; i < k; ++i) {
    int min_cost = 2000000000;
    for (int j = 0; j < (int)cart[i].size(); ++j) {
      ans += a[cart[i][j]] * 2;
      min_cost = min(min_cost, a[cart[i][j]]);
    }
    if (b[cart[i][0]] == 1) {
      ans -= min_cost;
    }
  }
  cout << ans / 2;
  if (ans % 2 == 0) {
    cout << ".0" << endl;
  } else {
    cout << ".5" << endl;
  }
  for (int i = 0; i < k; ++i) {
    cout << cart[i].size();
    for (int j = 0; j < (int)cart[i].size(); ++j) {
      cout << ' ' << cart[i][j] + 1;
    }
    cout << endl;
  }
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int Maxn = 5005;
const int Maxl = 26;
char a[Maxn], b[Maxn];
int alen, blen;
int freq[Maxl];
bool Possible(int pos) {
  int cur = Maxl - 1, tk = 0;
  for (int i = pos; i < blen; i++) {
    while (cur >= 0 && tk == freq[cur]) {
      cur--;
      tk = 0;
    }
    if (cur > b[i] - 'a') return true;
    if (cur < b[i] - 'a') return false;
    tk++;
  }
  while (cur >= 0 && tk == freq[cur]) {
    cur--;
    tk = 0;
  }
  return cur >= 0;
}
bool getMore(char lim, char &bet) {
  for (bet = lim + 1; bet - 'a' < Maxl; bet++)
    if (freq[bet - 'a']) return true;
  return false;
}
void writeTo(int pos) {
  for (int i = 0; i < Maxl; i++)
    while (freq[i]--) a[pos++] = 'a' + i;
  printf("%s\n", a);
}
int main() {
  scanf("%s", a);
  alen = strlen(a);
  scanf("%s", b);
  blen = strlen(b);
  for (int i = 0; i < alen; i++) freq[a[i] - 'a']++;
  if (!Possible(0))
    printf("-1\n");
  else {
    for (int i = 0; i < blen; i++) {
      if (freq[b[i] - 'a']) {
        freq[b[i] - 'a']--;
        if (Possible(i + 1)) {
          a[i] = b[i];
          continue;
        } else
          freq[b[i] - 'a']++;
      }
      char c;
      if (getMore(b[i], c)) {
        freq[c - 'a']--;
        a[i] = c;
        writeTo(i + 1);
        return 0;
      } else {
        printf("-1\n");
        return 0;
      }
    }
    writeTo(blen);
  }
  return 0;
}
