    if (b & 1) r = 1ll * r * a % mod;
    a = 1ll * a * a % mod;
  }
  return r;
}
int C(int a, int b) {
  int r = inv[b];
  for (b--; b >= 0; b--) r = 1ll * r * (a - b) % mod;
  return r;
}
