inline long long mypow(long long a, long long b) {
  int res = 1;
  while (b) {
    if (b & 1) {
      res = ((long long)res * a) % MOD;
    }
    a = ((long long)a * a) % MOD;
    b >>= 1;
  }
  return res;
}
inline long long cmb(long long a, long long b) {
  long long d1, d2;
  if (a < b) {
    return 0;
  }
  d1 = 1;
  d2 = inv2[b];
  while (b) {
    d1 = (long long)d1 * a % MOD;
    b--;
    a--;
  }
  return (long long)d1 * d2 % MOD;
}
bool calCurCom(long long n, int m) {
  if (n == 0) {
    return false;
  }
  int i;
  long long mul = 1;
  long long tmp = n;
  for (i = 1; i <= m; i++, tmp++) {
    mul = mul * tmp % MOD;
    curCom[i] = mul * inv2[i] % MOD;
  }
  return true;
}
int main() {
  int n, d, i, j, k, l, m;
  scanf("%d%d%lld", &n, &d, &MOD);
