  inv2[1] = 1;
  for (i = 2; i <= d; i++) {
    tmp = tmp * i;
    inv2[i] = mypow(tmp, MOD - 2);
  }
  for (k = 0; k <= n; k++) {
    dp[1][0][k] = 1;
  }
  for (i = 2; i <= d + 1; i++) {
    for (k = 1; k <= n; k++) {
      dp[i][i - 1][k] = 1;
    }
  }
  for (i = 3; i <= n; i++) {
    for (j = 1; j <= d && j < i - 1; j++) {
      for (k = 2; k <= n - 1; k++) {
        dp[i][j][k] = dp[i][j][k - 1];
        if (calCurCom(dp[k][d - 1][k - 1], j)) {
          for (l = 1; l <= j && l * k < i; l++) {
            tmp = (long long)dp[i - k * l][j - l][k - 1] * curCom[l] % MOD;
            dp[i][j][k] = ((long long)dp[i][j][k] + tmp) % MOD;
          }
        }
      }
    }
  }
  long long ans = 0;
  ans = dp[n][d][(n + 1) / 2 - 1];
  if ((n & 1) == 0) {
    ans = ((long long)ans + cmb(dp[n / 2][d - 1][n / 2 - 1] + 1, 2)) % MOD;
  }
  printf("%lld\n", ans);
