    memset(dp[now], 0, sizeof(dp[now]));
    for (int j = 0; j <= n; j++)
      for (int k = 0; k <= n; k++) {
        dp[now][j + 1][max(j + 1, k)] =
            (dp[now][j + 1][max(j + 1, k)] + dp[pre][j][k]) % mod;
        dp[now][1][max(1, k)] = (dp[now][1][max(1, k)] + dp[pre][j][k]) % mod;
      }
  }
