int dp(vector<int> &a, vector<int> &b, int i, int j)
{
    if(mem[i][j]!=-1)
        return mem[i][j];

    if(i>=a.size())
        return 0;

    if(j>=b.size())
        return inf;

    int temp=inf;
    int paired=dp(a,b,i+1,j+1);
    int not_paired=dp(a,b,i,j+1);
