void upd(int idx) {
  int l = idx * 2, r = idx * 2 + 1;
  if (tr[l] == -1 || tr[r] == -1) {
    tr[idx] = max(tr[l], tr[r]);
  } else {
    (a[tr[l]] >= a[tr[r]] ? tr[idx] = tr[l] : tr[idx] = tr[r]);
  }
}
void build(int idx, int l, int r) {
  if (l == r) {
    tr[idx] = l;
    return;
  }
