  build(idx * 2, l, m);
  build(idx * 2 + 1, m + 1, r);
  upd(idx);
}
int get(int idx, int l, int r, int ll, int rr) {
  if (l >= ll && r <= rr) {
    return tr[idx];
  }
  if (ll > r || rr < l) {
    return -1;
  }
  int m = (l + r) >> 1;
  int fi = get(idx * 2, l, m, ll, rr);
  int se = get(idx * 2 + 1, m + 1, r, ll, rr);
  if (fi == -1) {
    return se;
  }
  if (se == -1) {
    return fi;
  }
  return (a[fi] >= a[se] ? fi : se);
}
