long long query(long long L, long long R) {
  long long k = log2(R - L + 1);
  if (spt[L][k] >= spt[R - (1 << k) + 1][k]) {
    return idx[L][k];
  } else {
    return idx[R - (1 << k) + 1][k];
  }
