      return (cur > 0) ^ rev;
    if ((cur = cmp_substring(slen + 1, q - tlen, tlen)) != 0)
      return (cur > 0) ^ rev;
  } else {
    if ((cur = cmp_substring(slen + 1, p, q - p)) != 0) return (cur < 0) ^ rev;
    if ((cur = cmp_substring(slen + 1 + q - p, slen + 1, tlen - q + p)) != 0)
