              cur, patrick.query(
                       modulo_seg_start[rem] +
                           (int)floor((double)(l[i] - rem - 1) / cur_k) + 1,
                       modulo_seg_start[rem] +
                           (int)floor((double)(r[i] - rem) / cur_k)));
        }
