  if (u == rt) {
    l[u] = 0;
  } else {
    l[u] = l[fa] + 1;
  }
  f[u][0] = fa;
  for (int i = 1; (1 << i) <= l[u]; i++) {
    f[u][i] = f[f[u][i - 1]][i - 1];
    flag[u][i] = flag[u][i - 1] | flag[f[u][i - 1]][i - 1];
  }
