int lca1(int u, int v) {
  if (l[u] >= l[v]) return 0;
  int tu = 0, tv = 0;
  if (l[u] < l[v]) swap(u, v);
  int k = 0;
  while ((1 << (k + 1)) <= l[u] - l[v]) k++;
  while (l[u] > l[v]) {
    while ((1 << k) > l[u] - l[v]) k--;
    tu |= flag[u][k];
    u = f[u][k];
  }
  if (u != v)
    return 0;
  else
    return tu == 1;
}
int lca2(int u, int v) {
  int tu = 0, tv = 0, s = 0, t = flag[v][0];
  if (l[u] < l[v]) {
    swap(u, v);
    s = 1;
  }
  int k = 0;
  while ((1 << (k + 1)) <= l[u] - l[v]) k++;
  while (l[u] > l[v]) {
    while ((1 << k) > l[u] - l[v]) k--;
    tu |= flag[u][k];
    u = f[u][k];
  }
  if (u == v) {
    if (!s)
      return 0;
    else
      return tu == 2;
  }
  k = 0;
  while ((1 << (k + 1)) <= l[v]) k++;
  while (k >= 0) {
    while ((1 << k) > l[u]) k--;
    if (f[u][k] != f[v][k]) {
      tu |= flag[u][k];
      tv |= flag[v][k];
      u = f[u][k];
      v = f[v][k];
    } else
      k--;
  }
  tu |= flag[u][0];
  tv |= flag[v][0];
  if (s) swap(tu, tv);
  return tv == 2 && tu == 1;
}
