using namespace std;

typedef long long LL;

LL mod = 1000000007;

LL mi (LL x, LL m) {
	// compute pow(x, m-2)
	LL acc = 1;
	LL p = m-2;
	while (p) {
		if (p%2 == 1) {
			acc *= x;
			acc %= m;
		}
		x *= x % m;
		x %= m;
		p >>= 1;
	}

	return acc;
}

int main()
{
