	for (LL i = 1; i < n-1; ++i) {
		mijs[i]=mijs[i-1]+mi(i+1, mod);
		mijs[i]%=mod;
	}

	LL sum = 0;
	for (LL i = 0; i < n-1; ++i) {
		sum += (x[i+1]-x[i])*mijs[i] % mod;
		sum %= mod;
	}

	for (LL i = 1; i <= n-1; ++i) {
		sum *= i;
		sum %= mod;
	}

	cout << sum << "\n";

}

