const int MAX_N = (int)3e5 + 5;
int N, P[MAX_N], loc[MAX_N];
vector<pair<int, int> > ans;
void solve(int x) {
  int idx = loc[x];
  while (x != idx) {
    int idx2 = -1, val = -1;
    if (abs(x - idx) >= N / 2)
      idx2 = x, val = P[x];
    else {
      if (idx < N / 2)
        idx2 = N - 1, val = P[N - 1];
      else
        idx2 = 0, val = P[0];
    }
    ans.emplace_back(pair<int, int>(idx + 1, idx2 + 1));
    swap(P[idx], P[idx2]), swap(loc[x], loc[val]);
    idx = idx2;
  }
}
