  cin >> N;
  for (int i = 0; i < N; i++) {
    cin >> P[i], P[i]--;
    loc[P[i]] = i;
  }
  for (int i = 0; i < N / 2; i++) {
    solve(N / 2 - i - 1);
    solve(N / 2 + i);
  }
  printf("%d\n", ans.size());
  for (auto p : ans) printf("%d %d\n", p.first, p.second);
  return 0;
