vector<int> bfs(vector<vector<int> > adj, int src) {
  queue<int> q;
  q.push(src);
  vector<int> dst(adj.size(), INF);
  dst[src] = 0;
  while (!q.empty()) {
    int c = q.front();
    q.pop();
    for (int nbr : adj[c]) {
      if (dst[nbr] == INF) {
        dst[nbr] = dst[c] + 1;
        q.push(nbr);
      }
    }
  }
  return dst;
}
vector<int> bfsParents(vector<vector<int> > adj, int src) {
  vector<int> parents = vector<int>(adj.size(), INF);
  parents[src] = -1;
  queue<int> q;
  q.push(src);
  vector<int> dst(adj.size(), INF);
  dst[src] = 0;
  while (!q.empty()) {
    int c = q.front();
    q.pop();
    for (int nbr : adj[c]) {
      if (dst[nbr] == INF) {
        parents[nbr] = c;
        dst[nbr] = dst[c] + 1;
        q.push(nbr);
      }
    }
  }
  return parents;
}
