int iid = 0;
void go(int a, int b) {
    if (nid[a][b] != -1)  return;
    nid[a][b] = iid++;
    for (int i=0; i<26; i++) {
        if (!tr[a][i] || !tr[b][i])     continue;
        int na = tr[a][i], nb = tr[b][i];
        addtr(a, b, na, nb, i);
        if (leaf[na])       addtr(a, b, 0, nb, i);
        if (leaf[nb])       addtr(a, b, na, 0, i);
        if (leaf[na] && leaf[nb])       addtr(a, b, 0, 0, i);
    }

}

const int M = 998244353;

typedef vector<long long> row;
