            else{
                ll ones = min(boost - acquired_boost, v[i].second);
                ans += ones * 2 + (v[i].second - ones) * 1;
            }
        }
        debug(i, bought, ans, buf);
    }
    debug(bought);
    assert(bought == suf[0]);
