};
Interval mergeInterval(Interval a, Interval b) {
  Interval res;
  res.bestL = max(a.bestL, b.bestL);
  res.bestR = max(a.bestR, b.bestR);
  res.bestLR = max(a.bestLR, b.bestLR);
  res.bestLR = max(res.bestLR, a.bestL + b.bestR);
  return res;
}
