template <class A, class B>
bool maxi(A &a, const B &b) {
  return (a < b) ? (a = b, true) : false;
};
template <class A, class B>
bool mini(A &a, const B &b) {
  return (a > b) ? (a = b, true) : false;
};
const int maxN = 1e5 + 5;
const double oo = 1.0 / 0.0, eps = 1e-9, pi = atan2(1, 1) * 4;
