  map<int, int> res;
  for (int i = 2; i * i <= val; i++) {
    if (val % i == 0) {
      res[i] = 0;
      while (val % i == 0) {
        res[i] += 1;
        val /= i;
      }
    }
  }
  if (val > 1) {
    res[val] = 1;
  }
  return res;
}
