int token;

void next() {
    while (_ix < _s.size() && isspace(_s[_ix])) _ix++;
    if (_ix == _s.size()) {
        token = 0;
        return ;
    }
    if (!isdigit(_s[_ix])) {
        token = _s[_ix++];
    }
    else {
        int a = 0;
        while (isdigit(_s[_ix])) a = a*10+(_s[_ix++]-'0');
