		}
		priority_queue<speP> q;
		q.push({ 0,s }); d[s] = 0;
		while (!q.empty()) {
			speP x = q.top(); q.pop();
			int v = x.second;
			if (x.first > d[v])continue;
			int len = G[v].size();
			rep(j, len) {
