double distance(){
    double rA=radius(A), rB=radius(B);
    double lb=0, ub=rA+rB, d;
    for(int i=0;i<50;i++){
        d = (lb+ub)/2;
        double thetaA = acos((d*d+rA*rA-rB*rB)/(2*rA*d));
        double thetaB = acos((d*d+rB*rB-rA*rA)/(2*rB*d));
        double S = A*thetaA/M_PI + B*thetaB/M_PI - d*rA*sin(thetaA);
        if(S<AB){
            ub = d;
        }else{
            lb = d;
        }
    }
    return d;
}

