int main() {
    int N;
    cin >> N;
    string t;
    vector<string> s(N);
    for(int i = 0; i < N; ++i) {
        cin >> s[i];
    }
    cin >> t;

    aho_corasick aho(s);
    ll res = 0;
    auto match_pos = aho.match(t, s, res);
    cout << res << endl;
}

