	flow = max_flow(l, r);
	if (n - flow < k) {
		cout << -1 << endl; return;
	}
	vector<int> ans;
    int cur = 0;
    int use = 0;
    while(cur<n){
        if(banned[cur]){
            ++cur;
            continue;
        }
        ++use;
        del(cur);
        vector<int> dels;
        for(auto &e : G[cur]){
            if(e.to!=l&&e.to!=r&&!banned[e.to]){
                dels.push_back(e.to);
                del(e.to);
            }
        }
        flow += max_flow(l, r);
        if(rest-flow+use>=k){
            ans.push_back(cur);
        }
        else {
            --use;
            for(auto e : dels)add(e);
            flow += max_flow(l,r);
        }
        ++cur;
    }
	rep(i,k) {
		cout << ans[i]+1 << endl;
	}
}

