      sal[0] = sal[n + 1] = 0;
      sar[0] = sar[n + 1] = 0;
      sbl[0] = sbl[n + 1] = 0;
      sbr[0] = sbr[n + 1] = 0;
    }
    for (register int i = (1); i <= (n); ++i)
      scanf("%lld", a + i), sumaL[i] = sumaL[i - 1] + a[i];
    for (register int i = (1); i <= (n); ++i)
