      if (i == n) {
        res = max(res, ans);
        continue;
      }
      ++t;
      if (i & 1) {
        ans += t * b[i + 1];
        if (i < n - 1) downToRight(ans, i + 1, n, t);
      } else {
        ans += t * a[i + 1];
        if (i < n - 1) upToRight(ans, i + 1, n, t);
      }
    }
    printf("%lld\n", res);
  }
  return 0;
}
