  long long tmp = a;
  while (b) {
    if (b & 1) {
      res = mul(res, tmp);
    }
    tmp = mul(tmp, tmp);
    b >>= 1;
  }
  return res;
}
long long inv(long long a) { return bin_pow(a, mod - 2); }
