struct Node {
  int sum;
  Node *lson, *rson;
  void pushup() { sum = (lson ? lson->sum : EPT) + (rson ? rson->sum : EPT); }
} pool[3000010], *CUR;
void Update(Node *&T, int l, int r, int pos, int x) {
  if (!T) T = CUR++, T->sum = EPT, T->lson = T->rson = NULL;
  if (l == r) {
    T->sum = T->sum + x;
    return;
  }
  int mid = l + r >> 1;
  if (pos <= mid)
    Update(T->lson, l, mid, pos, x);
  else
    Update(T->rson, mid + 1, r, pos, x);
  T->pushup();
}
int Query(Node *T, int l, int r, int L, int R) {
  if (!T) return EPT;
  if (l == L && r == R) return T->sum;
  int mid = l + r >> 1;
  if (R <= mid) return Query(T->lson, l, mid, L, R);
  if (L > mid) return Query(T->rson, mid + 1, r, L, R);
  return Query(T->lson, l, mid, L, mid) +
         Query(T->rson, mid + 1, r, mid + 1, R);
}
Node *Merge(Node *L, Node *R) {
  if (!L || !R) return L ? L : R;
  L->sum = L->sum + R->sum;
  L->lson = Merge(L->lson, R->lson);
  L->rson = Merge(L->rson, R->rson);
  return L;
}
struct Block {
