Block Merge(Block A, Block B, int x, int lca, int K) {
  if (A.a == NULL || B.a == NULL) return A.a == NULL ? B : A;
  if (A.a->size() < B.a->size()) swap(A, B);
  for (vector<int>::iterator it = B.a->begin(); it != B.a->end(); it++) {
    int y = *it;
    A.a->push_back(y);
