      int p = get_par(u, dep[u] - dep[x] - K);
      ans += query(id[p] + sz[p] - 1) - query(id[p] - 1);
    }
    if (dep[v] - dep[x] >= K) {
      int p = get_par(v, dep[v] - dep[x] - K);
      ans += query(id[p] + sz[p] - 1) - query(id[p] - 1);
    }
    modify(id[u], 1), modify(id[v], 1);
  }
  for (int i = 0; i < from[x].size(); i++) {
    int v = from[x][i];
    if (v == last) continue;
