void rec(int g, int l, int r, int kl, int kr) {
  if (l > r) return;
  int mid = (l + r) / 2;
  dp[mid][g] = 1111111111111111111ll;
  int bestk = -1;
  for (int i = kl; i <= kr; i++) {
    if (i > mid) break;
    long long int now = dp[i][g - 1] + cost(i + 1, mid);
    if (now < dp[mid][g]) {
      dp[mid][g] = now;
      bestk = i;
    }
  }
  rec(g, l, mid - 1, kl, bestk);
  rec(g, mid + 1, r, bestk, kr);
}
