  makesu();
  scanf("%d%d", &n, &m);
  for (i = 1; i <= n; i++) scanf("%d", &a[i]), make(i);
  for (i = 1; i <= m; i++) {
    scanf("%d", &x);
    if (check[x])
      del(x), check[x] = 0;
    else
      add(x), check[x] = 1;
    cout << ans << endl;
  }
  return 0;
}

