  register char c = getchar();
  for (; !isdigit(c); c = getchar())
    if (c == '-') f = -1;
  for (; isdigit(c); c = getchar()) x = (x << 1) + (x << 3) + (c ^ 48);
  return x * f;
}
struct Edge {
  long long to, nxt, type;
  Edge() {}
  Edge(long long to, long long nxt, long long type)
      : to(to), nxt(nxt), type(type) {}
} edge[100099 * 2];
long long first[100099], nume;
void Addedge(long long a, long long b, long long c) {
  edge[nume] = Edge(b, first[a], c);
  first[a] = nume++;
}
long long fa[100099], son[100099], size[100099], up[100099], down[100099],
    top[100099], n;
long long deep[100099];
long long Pow[1000009];
void dfs1(long long u, long long f) {
  size[u] = 1;
  son[u] = 0;
  for (long long e = first[u]; ~e; e = edge[e].nxt) {
    long long v = edge[e].to;
    if (v != f) {
      deep[v] = deep[u] + 1;
      dfs1(v, u);
      size[u] += size[v];
      fa[v] = u;
      if (size[son[u]] < size[v]) son[u] = v;
    }
  }
}
void dfs2(long long u, long long chain) {
  top[u] = chain;
  if (son[u]) dfs2(son[u], chain);
  for (long long e = first[u]; ~e; e = edge[e].nxt) {
    long long v = edge[e].to;
    if (v != son[u] && v != fa[u]) dfs2(v, v);
  }
}
long long lca(long long x, long long y) {
  while (top[x] != top[y])
    if (deep[top[x]] > deep[top[y]])
      x = fa[top[x]];
    else
      y = fa[top[y]];
  return deep[x] > deep[y] ? y : x;
}
long long ans;
void dfs(long long u) {
  for (long long e = first[u]; ~e; e = edge[e].nxt) {
    long long v = edge[e].to;
    if (v == fa[u]) continue;
    dfs(v);
    if (edge[e].type == 1)
      ans = (ans + Pow[up[v]] - 1 + 1000000007) % 1000000007;
    if (edge[e].type == 2)
      ans = (ans + Pow[down[v]] - 1 + 1000000007) % 1000000007;
    up[u] += up[v];
    down[u] += down[v];
  }
}
signed main() {
  n = read();
  Pow[0] = 1;
  for (long long i = 1; i <= 1000000; i++)
    Pow[i] = 1LL * Pow[i - 1] * 2 % 1000000007;
  memset(first, -1, sizeof(first));
  nume = 0;
  for (long long i = 1; i < n; i++) {
    long long a = read(), b = read(), c = read();
    if (!c) {
      Addedge(a, b, 0);
      Addedge(b, a, 0);
    } else {
      Addedge(a, b, 1);
      Addedge(b, a, 2);
    }
  }
  size[0] = 0;
  deep[1] = 0;
  dfs1(1, 0);
  dfs2(1, 1);
  memset(up, 0, sizeof(up));
  memset(down, 0, sizeof(down));
  long long K = read();
  long long last = 1;
  for (long long i = 1; i <= K; i++) {
    long long now = read();
    long long tmp = lca(last, now);
    up[last]++;
    up[tmp]--;
    down[now]++;
    down[tmp]--;
    last = now;
  }
  ans = 0;
  dfs(1);
  printf("%I64d\n", ans);
  return 0;
}
#include <bits/stdc++.h>
using namespace std;
struct edge {
  int a, b, x;
} e[100010];
int d[100010], E[2 * 100010], F[100010], L[100010], rmq[18][2 * 100010],
    repr[100010];
int s[10 * 100010], pre[2 * 100010], pw[10 * 100010];
int t, n, k;
vector<pair<int, int> > T[100010];
void euler(int x, int f) {
  d[x] = d[f] + 1;
  E[++t] = x;
  F[x] = t;
  for (int i = 0; i < T[x].size(); ++i) {
    int y = T[x][i].first;
    if (y != f) {
      repr[T[x][i].second] = y;
      euler(y, x);
      E[++t] = x;
    }
  }
  L[x] = t;
}
int lca(int a, int b) {
  a = F[a];
  b = F[b];
  if (a > b) swap(a, b);
  int l = log2(b - a + 1);
  if (d[rmq[l][a]] < d[rmq[l][b - (1 << l) + 1]]) return rmq[l][a];
  return rmq[l][b - (1 << l) + 1];
}
int main() {
  scanf("%d", &n);
  for (int i = 1; i < n; ++i) {
    int a, b, x;
    scanf("%d %d %d", &a, &b, &x);
    e[i].a = a;
    e[i].b = b;
    e[i].x = x;
    T[a].push_back(make_pair(b, i));
    T[b].push_back(make_pair(a, i));
  }
  scanf("%d", &k);
  for (int i = 1; i <= k; ++i) {
    scanf("%d", &s[i]);
  }
  euler(1, 0);
  for (int i = 1; i <= t; ++i) {
    rmq[0][i] = E[i];
  }
  for (int i = 1; (1 << i) <= t; ++i) {
    for (int j = 1; j + (1 << i) - 1 <= t; ++j) {
      if (d[rmq[i - 1][j]] < d[rmq[i - 1][j + (1 << (i - 1))]])
        rmq[i][j] = rmq[i - 1][j];
      else
        rmq[i][j] = rmq[i - 1][j + (1 << (i - 1))];
    }
  }
  pre[F[s[1]]]++;
  pre[F[1]]--;
  for (int i = 1; i < k; ++i) {
    int a = s[i];
    int b = s[i + 1];
    int l = lca(a, b);
    pre[F[l]] -= 2;
    pre[F[a]]++;
    pre[F[b]]++;
  }
  for (int i = 1; i <= t; ++i) pre[i] = pre[i - 1] + pre[i];
  pw[0] = 1;
  for (int i = 1; i <= k; ++i) {
    pw[i] = pw[i - 1] * 2;
    if (pw[i] >= 1000000007) pw[i] -= 1000000007;
  }
  int ans = 0;
  for (int i = 1; i < n; ++i) {
    int trav = pre[L[repr[i]]] - pre[F[repr[i]] - 1];
    if (e[i].x == 1) {
      if (d[e[i].a] < d[e[i].b]) {
        ans = (ans + pw[trav / 2] - 1);
        if (ans >= 1000000007) ans -= 1000000007;
        if (ans < 0) ans += 1000000007;
      } else {
        ans = (ans + pw[(trav + 1) / 2] - 1);
        if (ans >= 1000000007) ans -= 1000000007;
        if (ans < 0) ans += 1000000007;
      }
    }
  }
  cout << ans;
}

