  for (int i = 0; i < n; i++)
    for (int j = 0; j < m; j++) {
      char c = '\n';
      while (c == '\n') scanf("%c", &c);
      data[i * m + j] = c - '0';
    }
  for (int i = 0; i < 10; i++) scanf("%d%d", &X[i], &Y[i]);
}
