int next(int u) {
  int x = u / m, y = u % m;
  x += X[data[u]];
  y += Y[data[u]];
  int v;
  if (x >= n || y >= m || x < 0 || y < 0)
    v = u;
  else
    v = x * m + y;
  return v;
}
void find_cir(int u) {
  vis[u] = -1;
  int v = N[u];
  if (vis[v] != 1) {
    if (vis[v] == -1)
      iscir[v] = 1;
    else
      find_cir(v);
  }
  vis[u] = 1;
}
void get_cir(int i, int u) {
  cir[i][data[u]] = 1;
  vis[u] = 1;
  int v = N[u];
  if (vis[v]) return;
  get_cir(i, v);
}
