  int len = strlen(s);
  for (int i = len - 1; i >= 0; i--) {
    memset(is[i], false, sizeof(is[i]));
    if (i != len - 1)
      for (int j = 0; j < 10; j++) is[i][j] = is[i + 1][j];
    is[i][s[i] - '0'] = true;
  }
  for (int i = 0; i < n * m; i++)
    if (ishead[i]) {
      int u = i, cur = 0;
