        while (s[cur] - '0' != data[u]) {
          u = N[u];
          if (iscir[u]) break;
        }
        if (!iscir[u]) {
          u = N[u];
          cur++;
          if (cur == len) return true;
        }
      }
      int flag = 1;
      for (int j = 0; j < 10; j++)
        if (is[cur][j] && !cir[u][j]) flag = 0;
      if (flag) return true;
    }
  return false;
