void prepare() {
  static queue<int> q;
  static bool vis[maxn];
  memset(dis, inf, sizeof(dis));
  for (int i = 1; i <= n; i++) {
    int *d = dis[i];
    d[i] = 0;
    vis[i] = true;
    q.push(i);
    while (!q.empty()) {
      int cn = q.front();
      q.pop();
      vis[cn] = false;
      for (int i = fst[cn]; i; i = nxt[i]) {
        if (d[v[i]] > d[cn] + 1) {
          d[v[i]] = d[cn] + 1;
          if (!vis[v[i]]) {
            vis[v[i]] = true;
            q.push(v[i]);
          }
        }
      }
    }
  }
  static int stamp[maxn];
  for (int i = 1; i <= n; i++) {
    static int counter;
    counter++;
    for (int k = 1; k <= 4; k++) {
      pair<int, int> mx = make_pair(-inf, 0);
      for (int j = 1; j <= n; j++) {
        if (stamp[j] == counter || dis[j][i] == inf || j == i) continue;
        chkmax(mx, make_pair(dis[j][i], j));
      }
      in[i][k] = mx;
      stamp[mx.second] = counter;
    }
    counter++;
    for (int k = 1; k <= 4; k++) {
      pair<int, int> mx = make_pair(-inf, 0);
      for (int j = 1; j <= n; j++) {
        if (stamp[j] == counter || dis[i][j] == inf || j == i) continue;
        chkmax(mx, make_pair(dis[i][j], j));
