  int ans = 0;
  int a, b, c, d;
  for (int i = 1; i <= n; i++) {
    vis[i] = true;
    for (int j = 1; j <= n; j++) {
      if (i != j && dis[i][j] < inf) {
        vis[j] = true;
        for (int k = 1; k <= 4; k++) {
          if (!vis[in[i][k].second]) {
            int fr = in[i][k].second;
            vis[fr] = true;
            for (int p = 1; p <= 4; p++) {
              if (!vis[out[j][p].second]) {
                int to = out[j][p].second;
                vis[to] = true;
                if (dis[fr][i] < inf && dis[j][to] < inf) {
                  if (dis[fr][i] + dis[i][j] + dis[j][to] > ans) {
                    ans = dis[fr][i] + dis[i][j] + dis[j][to];
                    a = fr, b = i, c = j, d = to;
                  }
                }
                vis[to] = false;
                break;
              }
            }
            vis[fr] = false;
            break;
          }
        }
        for (int k = 1; k <= 4; k++) {
          if (!vis[out[j][k].second]) {
            int to = out[j][k].second;
            vis[to] = true;
            for (int p = 1; p <= 4; p++) {
              if (!vis[in[i][p].second]) {
                int fr = in[i][p].second;
                vis[fr] = true;
                if (dis[fr][i] < inf && dis[j][to] < inf) {
                  if (dis[fr][i] + dis[i][j] + dis[j][to] > ans) {
