#include <bits/stdc++.h>
using namespace std;
const int N = 200500;
struct state {
  int len, link;
  map<char, int> next;
};
state st[N];
int sz, last;
void sa_init() {
  last = st[0].len = 0;
  sz = 1;
  st[0].link = -1;
}
void sa_extend(char c) {
  int k = sz++, p;
  st[k].len = st[last].len + 1;
  for (p = last; p != -1 && !st[p].next.count(c); p = st[p].link)
    st[p].next[c] = k;
  if (p == -1)
    st[k].link = 0;
  else {
    int q = st[p].next[c];
    if (st[p].len + 1 == st[q].len)
      st[k].link = q;
    else {
      int w = sz++;
      st[w].len = st[p].len + 1;
      st[w].next = st[q].next;
      st[w].link = st[q].link;
      for (; p != -1 && st[p].next[c] == q; p = st[p].link) st[p].next[c] = w;
      st[q].link = st[k].link = w;
    }
  }
  last = k;
}
string s;
long long dp[N];
bool t[N];
long long f(int i) {
  if (dp[i] != -1) return dp[i];
  long long &r = dp[i] = t[i];
  for (auto p : st[i].next) r += f(p.second);
  return r;
}
void solve() {
  sa_init();
  memset(dp, -1, sizeof dp);
  for (int i = 0, qwerty = ((int)(s).size()); i < qwerty; i++) sa_extend(s[i]);
  int x = last;
  while (x) {
    t[x] = 1;
    x = st[x].link;
  }
  f(0);
  long long r = 0;
  for (int i = 1, qwerty = sz; i < qwerty; i++)
    r += f(i) * f(i) * (st[i].len - st[st[i].link].len);
  while (last) {
    t[last] = 0;
    last = st[last].link;
  }
  for (int i = 0, qwerty = sz; i < qwerty; i++) st[i].next.clear();
  cout << r << "\n";
}
int main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  cout.tie(0);
  int tn;
  cin >> tn;
  for (int i = 0, qwerty = tn; i < qwerty; i++) {
    cin >> s;
    solve();
  }
}
#include <bits/stdc++.h>
using namespace std;
const int MN = 1e5 + 10, LG = 18;
pair<pair<int, int>, int> T[MN];
int P[LG][MN], p[MN], rev[MN], lcp[MN], n;
string s;
void Ok(int i) {
  for (int j = 0; j < n; ++j)
    P[i][T[j].second] =
        j && T[j].first == T[j - 1].first ? P[i][T[j - 1].second] : j;
}
void prep() {
  for (int i = 0; i < n; ++i) T[i] = {{s[i], s[i]}, i};
  sort(T, T + n);
  Ok(0);
  for (int i = 1; i < LG; ++i) {
    for (int j = 0; j < n; ++j)
      T[j] = {{P[i - 1][j],
               j + (1 << (i - 1)) < n ? P[i - 1][j + (1 << (i - 1))] : -1},
              j};
    sort(T, T + n);
    Ok(i);
  }
  for (int i = 0; i < n; ++i) p[i] = P[LG - 1][i], rev[p[i]] = i;
  int pnt = 0;
  for (int i = 0; i < n; ++i) {
    pnt = max(pnt, 0);
    if (p[i] == n - 1)
      pnt = 0;
    else {
      int x = rev[p[i] + 1];
      while (max(x, i) + pnt < n && s[i + pnt] == s[x + pnt]) ++pnt;
    }
    lcp[p[i]] = pnt--;
  }
}
int main() {
  ios_base ::sync_with_stdio(false), cin.tie(0), cout.tie(0);
  int Tst;
  cin >> Tst;
  while (Tst--) {
    cin >> s;
    n = ((int)(s).size());
    prep();
    set<int> S = {-1, n - 1};
    set<int>::iterator it;
    long long ans = 0;
    for (int i = 0; i < n; ++i) T[i] = {{lcp[i], 0}, i};
    sort(T, T + n);
    for (int i = 0; i < n; ++i) {
      int id = T[i].second;
      it = S.upper_bound(id);
      int x = *it - id;
      --it;
      int y = id - *it;
      S.insert(id);
      ans += 1ll * x * y * T[i].first.first;
    }
    cout << 2 * ans + 1ll * n * (n + 1) / 2 << '\n';
  }
  return 0;
}
